376	  body.drive #drGas,body.drive #drBrake{display:flex;align-items:center;justify-content:center;position:fixed;pointer-events:auto;touch-action:none;margin:0;padding:0;box-sizing:border-box;color:var(--text);background:rgba(10,18,22,.5);border:2px solid var(--panel-line);border-radius:18px;font:700 14px/1.1 var(--font-body);text-align:center;cursor:pointer;-webkit-tap-highlight-color:transparent;}
377	  body.drive #drGas{right:calc(16px + env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-gas-w,92px),24vw);height:var(--dr-gas-h,124px);}
378	  body.drive #drBrake{right:calc(26px + min(var(--dr-gas-w,92px),24vw) + env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-brake-w,76px),19vw);height:var(--dr-brake-h,84px);}
379	  body.drive #drGas.on{background:rgba(230,189,106,.6);border-color:var(--gold);}
380	  body.drive #drBrake.on{background:rgba(214,70,60,.6);border-color:#e86a5e;}
381	  body.drive #drMap{left:calc(8px + env(safe-area-inset-left,0px));top:calc(56px + env(safe-area-inset-top,0px));bottom:auto;}   /* dưới hàng nút ⚙ / Thoát (hai góc trên; ar đổi chỗ hai nút) */
382	  body.drive #drMapNote{left:calc(8px + env(safe-area-inset-left,0px));top:calc(60px + var(--dr-map-h,128px) + env(safe-area-inset-top,0px));bottom:auto;font-size:10px;max-width:calc(50vw - 24px);}
383	  body.drive #drSpeed{right:auto;bottom:auto;left:50%;transform:translateX(-50%);top:calc(8px + env(safe-area-inset-top,0px));}
384	}
385	/* Dòng hướng dẫn phím của đi dạo (#stHint): cùng chỗ và kiểu với #exHint, chỉ khi có chuột (hover:hover) và không ở chế độ xem; cảm ứng đã có cần gạt */
386	#stHint{display:none;}
387	@media (hover:hover){
388	  body.explore.stroll:not(.ex-watching) #stHint{display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 200px);box-sizing:border-box;pointer-events:none;z-index:4;}
389	  body.compact.stroll #stHint{top:calc(64px + env(safe-area-inset-top,0px));}
390	}
391	body.stroll #scene{cursor:grab;}
392	body.stroll #scene:active{cursor:grabbing;}
393	/* Đi dạo: điều khiển cảm ứng (explore/stroll/touch.ts). #stHud là lớp phủ trong suốt, chỉ các điều khiển nhận chạm; direction:ltr để ar (RTL) vẫn giữ cần gạt bên trái tay.
394	   Bố cục B: cần gạt trái dưới; phải chỉ 📷; vuốt nửa phải để xoay camera. Cần gạt, vuốt chỉ hiện khi không có chuột (hover:none); 📷 hiện cả trên máy tính */
395	#stHud,#stPad,#stLook,#stPhoto,#stFlash{display:none;}
396	body.stroll #stHud{display:block;position:fixed;inset:0;z-index:4;pointer-events:none;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;}
397	body.ex-watching #stHud{display:none;}
398	#stHud button{position:fixed;align-items:center;justify-content:center;pointer-events:auto;touch-action:none;margin:0;padding:0;color:var(--text);background:var(--panel);border:1px solid var(--panel-line);border-radius:50%;font:600 13px/1 var(--font-body);cursor:pointer;-webkit-tap-highlight-color:transparent;}
399	body.stroll #stPhoto{display:flex;right:calc(14px + env(safe-area-inset-right,0px));top:calc(100px + env(safe-area-inset-top,0px));width:48px;height:48px;font-size:22px;}   /* dưới nút Thoát (top 56 px) */
400	body.compact.stroll #stPhoto{top:calc(60px + env(safe-area-inset-top,0px));}   /* nút Thoát cao 40 px ở top 8 px */
401	#stFlash{position:fixed;inset:0;background:#fff;opacity:0;pointer-events:none;}   /* chớp khi chụp (Task 9 bật bằng lớp .on) */
402	body.stroll #stFlash{display:block;}
403	#stFlash.on{opacity:.85;}
404	/* Thông báo chụp ảnh: ô riêng ở giữa mép trên (không dùng #exMpNotice của dù lượn nhiều người); chừa chỗ cho nút Thoát bên phải, hẹp thì xuống dòng */
405	#stToast{display:none;}
406	body.stroll #stToast:not([hidden]){display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);max-width:calc(100vw - 200px);box-sizing:border-box;text-align:center;pointer-events:none;z-index:5;}
407	body.compact.stroll #stToast:not([hidden]){top:calc(8px + env(safe-area-inset-top,0px));}
408	@media (hover:none){
409	  body.stroll #stPad{display:block;position:fixed;pointer-events:auto;touch-action:none;left:calc(24px + env(safe-area-inset-left,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:var(--st-pad,120px);height:var(--st-pad,120px);box-sizing:border-box;border-radius:50%;background:rgba(10,18,22,.4);border:2px solid var(--panel-line);}
410	  #stKnob{position:absolute;left:50%;top:50%;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;background:rgba(230,189,106,.55);border:1px solid var(--gold);pointer-events:none;}
411	  body.stroll #stLook{display:block;position:fixed;pointer-events:auto;touch-action:none;right:0;width:50%;top:calc(110px + env(safe-area-inset-top,0px));bottom:0;}   /* nửa phải, dưới nút Thoát và 📷 */
412	  body.stroll #exMpRoster:not([hidden]){inset-inline-end:auto;right:calc(14px + env(safe-area-inset-right,0px));}   /* ar: danh sách vẫn ở phải, không đè cần gạt bên trái */
413	}
414	body.compact #exHint{top:calc(64px + env(safe-area-inset-top,0px));}
415	body.compact #btnExExit{top:calc(8px + env(safe-area-inset-top,0px));inset-inline-end:calc(8px + env(safe-area-inset-right,0px));min-height:40px;}
