file.content:
.ex-card:disabled .ex-note{color:var(--gold);}
.ex-card:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
/* Ghi công mô hình VF 3 (CC BY 4.0, public/car/LICENSE-VF3.txt): dòng nhỏ cuối hộp, hiện cả ở màn chọn lẫn sảnh */
.ex-credit{margin:14px 0 0;font-size:11px;line-height:1.45;color:var(--muted);}
.ex-credit a{color:inherit;text-decoration:underline;text-underline-offset:2px;}
/* Bước chọn slot + nhập tên (dù lượn nhiều người): thay các thẻ trong cùng hộp thoại */
.ex-cards[hidden],.ex-mp-lobby [hidden],.ex-mp-lobby[hidden]{display:none;}
.ex-mp-lobby{display:flex;flex-direction:column;gap:10px;min-width:min(340px,100%);}
.ex-mp-lobby h2{margin:0;}
.ex-mp-seatline{display:flex;align-items:center;gap:10px;font-size:13px;color:var(--text);}
#exMpDots{display:inline-flex;gap:6px;flex:none;}
#exMpDots i{width:12px;height:12px;border-radius:50%;box-sizing:border-box;border:1.5px solid var(--gold);background:transparent;}
#exMpDots i.on{border-color:transparent;}
#exMpList{display:flex;flex-direction:column;font-size:13px;}
#exMpList .ex-mp-row{padding:4px 0;border-bottom:1px solid rgba(255,255,255,.08);overflow-wrap:anywhere;}
#exMpList .ex-mp-row i{width:9px;height:9px;border-radius:50%;flex:none;}
.ex-mp-field{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted);}
.ex-mp-field input{font:500 14px/1.2 var(--font-body);color:var(--text);background:rgba(0,0,0,.35);border:1px solid var(--gold);border-radius:4px;padding:8px 10px;box-sizing:border-box;width:100%;}
.ex-mp-field input:focus-visible{outline:2px solid var(--gold);outline-offset:1px;}
#exMpNameHint{font-size:11px;color:var(--muted);}
#exMpNameBad,#exMpOffline{font-size:12.5px;line-height:1.45;color:var(--gold);}
.ex-mp-btn{width:100%;padding:10px;font-weight:700;font-size:13px;color:#14191c;background:var(--gold);border-color:var(--gold);}
.ex-mp-btn:hover:not(:disabled){background:var(--gold);}
.ex-mp-btn:disabled{opacity:.45;cursor:not-allowed;}
.ex-mp-btn:focus-visible{outline:2px solid #fff;outline-offset:2px;}
.ex-mp-btn.ex-mp-alt{color:var(--text);background:transparent;border-color:var(--gold);font-weight:600;}   /* nút phụ: Quay lại, Bay một mình khi có máy chủ */
.ex-mp-btn.ex-mp-alt:hover:not(:disabled){background:rgba(255,255,255,.08);}
/* Khi bay: chỉ còn ngôn ngữ, Ngày/Đêm, Chất lượng hình, dòng hướng dẫn và nút Thoát; mọi nút góc nhìn / cầu / Tour ẩn để không thoát chế độ bay bằng đường khác */
#exHint,#exSpeed,#btnExExit,#exMpLabels,#exMpRoster,#exMpNotice{display:none;}
body.explore #exSpeed{display:block;position:fixed;left:50%;transform:translateX(-50%);bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:6px 14px;font-size:13px;color:var(--text);direction:ltr;font-variant-numeric:tabular-nums;white-space:nowrap;pointer-events:none;}
body.explore #exHint{display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 32px);box-sizing:border-box;}
body.explore #btnExExit{display:block;inset-inline-end:calc(14px + env(safe-area-inset-right,0px));top:calc(56px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);cursor:pointer;}
body.explore #exMpLabels{display:block;position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:5;}
.ex-mp-label{position:absolute;left:0;top:0;padding:2px 7px;font:500 11px/1.2 var(--font-body);color:var(--text);background:rgba(10,18,30,.72);border-radius:4px;white-space:nowrap;will-change:transform;direction:ltr;}
.ex-mp-label[hidden]{display:none;}
body.explore #exMpRoster:not([hidden]){display:flex;flex-direction:column;gap:3px;position:fixed;inset-inline-end:calc(14px + env(safe-area-inset-right,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:8px 12px;font-size:12px;color:var(--text);pointer-events:none;z-index:5;}
.ex-mp-head{font-weight:600;margin-bottom:2px;}
.ex-mp-row{display:flex;align-items:center;gap:6px;}
.ex-mp-row.me{font-weight:600;}
.ex-mp-row i{width:9px;height:9px;border-radius:50%;flex:none;}
.ex-mp-row.walk i{border-radius:2px;}   /* người đi dạo: chấm vuông, người bay: chấm tròn, người lái xe: chấm thoi */
.ex-mp-row.drive i{border-radius:2px;transform:rotate(45deg) scale(.85);}
body.explore #exMpNotice:not([hidden]){display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(100px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);z-index:5;}
/* Chế độ xem (hết chỗ hoặc vừa nhường chỗ): không có dù của mình nên ẩn dòng hướng dẫn lái và đồng hồ; hiện "Đang xem" và lời mời */
body.ex-watching #exHint,body.ex-watching #exSpeed{display:none;}
#exMpIdle{display:none;}
body.explore #exMpIdle:not([hidden]){display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(150px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:13px;color:var(--gold);max-width:calc(100vw - 32px);box-sizing:border-box;text-align:center;pointer-events:none;z-index:6;}
#exMpWatch,#exMpInvite{display:none;}
body.ex-watching #exMpWatch:not([hidden]){display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:13px;color:var(--text);max-width:calc(100vw - 32px);box-sizing:border-box;text-align:center;pointer-events:none;z-index:5;}
body.ex-watching #exMpInvite:not([hidden]){display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:center;position:fixed;left:50%;transform:translateX(-50%);bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:10px 14px;font-size:13px;color:var(--text);max-width:calc(100vw - 32px);box-sizing:border-box;z-index:6;}
#exMpInvite input{font:500 14px/1.2 var(--font-body);color:var(--text);background:rgba(0,0,0,.35);border:1px solid var(--gold);border-radius:4px;padding:7px 10px;width:130px;box-sizing:border-box;}
#exMpInvite input[hidden]{display:none;}
#exMpInvite .ex-mp-btn{width:auto;padding:8px 16px;}
.ex-mp-note{margin:0 0 12px;font-size:12.5px;line-height:1.45;color:var(--gold);}
.ex-mp-note[hidden]{display:none;}
body.explore .views,body.explore .specs,body.explore #tourCaption,body.explore #wxScenario,body.explore #hint,body.explore #swRideHint,body.explore #swStormNote,body.explore #hrLabels{display:none!important;}
body.explore h1,body.explore .eyebrow,body.explore #btnShadow,body.explore .audio-row,body.explore .slider,body.explore .weather-row,body.explore .donate{display:none!important;}
body.explore:not(.ex-test) .stats{display:none;}   /* HUD giữ khi URL có ?test để test đo draw call */
/* Đi dạo: dòng hướng dẫn và đồng hồ là của dù lượn nên ẩn; kéo chuột trên cảnh để xoay camera */
body.explore.stroll #exHint,body.explore.stroll #exSpeed{display:none;}
/* Lái xe (explore/drive): chữ và tốc độ của dù lượn ẩn; #drHud là khung HUD riêng (hud.ts, touch.ts): đồng hồ, bản đồ nhỏ, gợi ý phím, cần gạt + bàn đạp cảm ứng.
   Lớp phủ trong suốt, chỉ các điều khiển nhận chạm; direction:ltr (dir="ltr" trên #drHud) để ar (RTL) vẫn giữ cần gạt bên trái, bàn đạp bên phải, không lật. */
body.explore.drive #exHint,body.explore.drive #exSpeed{display:none;}
#drHud,#drLook,#drSteer,#drGas,#drBrake{display:none;}
body.drive #drHud{display:block;position:fixed;inset:0;z-index:4;pointer-events:none;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;}
#drMap,#drMapNote,#drSpeed,#drHint{position:fixed;pointer-events:none;}
#drMap{display:block;left:calc(14px + env(safe-area-inset-left,0px));bottom:calc(44px + env(safe-area-inset-bottom,0px));background:var(--panel);border:1px solid var(--panel-line);border-radius:6px;}   /* bản đồ nhỏ: dưới trái; Bắc ở trên */
#drMapNote{left:calc(14px + env(safe-area-inset-left,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:5px 9px 5px 22px;font-size:11px;line-height:1.2;color:var(--text);max-width:260px;box-sizing:border-box;}
#drMapNote::before{content:"";position:absolute;left:8px;top:50%;width:9px;height:9px;margin-top:-4.5px;border-radius:50%;background:#e08a3c;}   /* cùng màu ô hầm trên bản đồ (CONFIG.drive.hud.colors.tunnel) */
#drSpeed{right:calc(14px + env(safe-area-inset-right,0px));bottom:calc(14px + env(safe-area-inset-bottom,0px));padding:6px 14px;display:flex;align-items:baseline;gap:6px;color:var(--text);}   /* đồng hồ: dưới phải */
#drKmh{font:700 34px/1 var(--font-display);color:var(--gold);min-width:3ch;text-align:right;font-variant-numeric:tabular-nums;}
#drSpeedUnit{font-size:12px;}
#drHint{display:none;}
#drHint.off{opacity:0;transition:opacity .6s;}
@media (hover:hover){
  body.drive #drHint{display:block;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 200px);box-sizing:border-box;}
}
/* Lái xe nhiều người: danh sách người chơi lên góc trên phải, dưới nút Thoát (đáy phải dành cho đồng hồ tốc độ, đáy trái cho bản đồ nhỏ, đáy phải trên cảm ứng cho bàn đạp); ar vẫn ở bên phải.
   Z-index 5 / 6 của danh sách và lời mời trên #drHud (4) nên bấm được trên lớp vuốt #drLook. Ô FPS (.stats, chỉ khi ?test) nhấc lên khỏi đồng hồ. Chế độ xem: không điều khiển, ẩn bàn đạp / cần gạt / gợi ý phím */
body.drive #exMpRoster:not([hidden]){inset-inline-end:auto;right:calc(14px + env(safe-area-inset-right,0px));bottom:auto;top:calc(100px + env(safe-area-inset-top,0px));box-sizing:border-box;max-height:calc(100vh - 88px - var(--dr-gas-h,124px));overflow:hidden;}
body.compact.drive #exMpRoster:not([hidden]){top:calc(56px + env(safe-area-inset-top,0px));}
body.drive.ex-test .stats{inset-inline-end:auto;right:calc(14px + env(safe-area-inset-right,0px));bottom:calc(74px + env(safe-area-inset-bottom,0px));}   /* ar: vẫn ở phải (không sang trái đè bản đồ nhỏ) */
/* Điện thoại (compact): danh sách hẹp lại, xuống dòng khi chuỗi dài (ru); hai thông báo dời khỏi dải giữa trên để không đè danh sách (trên phải) và bản đồ nhỏ (trên trái):
   dọc: cột trái dưới bản đồ + chú thích; ngang: dải trái giữa bản đồ và danh sách, hẹp lại */
@media (hover:none){
  body.compact.drive #exMpRoster:not([hidden]){max-width:calc(50vw - 24px);}
  body.compact.drive #exMpNotice:not([hidden]),body.compact.drive #exMpIdle:not([hidden]){left:calc(8px + env(safe-area-inset-left,0px));transform:none;max-width:calc(50vw - 24px);box-sizing:border-box;text-align:start;}
  body.compact.drive #exMpNotice:not([hidden]){top:calc(60px + var(--dr-map-h,128px) + 76px + env(safe-area-inset-top,0px));}
  body.compact.drive #exMpIdle:not([hidden]){top:calc(60px + var(--dr-map-h,128px) + 76px + 70px + env(safe-area-inset-top,0px));}
}
@media (hover:none) and (orientation:landscape){
  body.compact.drive #exMpNotice:not([hidden]),body.compact.drive #exMpIdle:not([hidden]){left:calc(150px + env(safe-area-inset-left,0px));max-width:calc(50vw - 160px);}
  body.compact.drive #exMpNotice:not([hidden]){top:calc(56px + env(safe-area-inset-top,0px));}
  body.compact.drive #exMpIdle:not([hidden]){top:calc(120px + env(safe-area-inset-top,0px));}
}
body.drive.ex-watching #drSteer,body.drive.ex-watching #drGas,body.drive.ex-watching #drBrake,body.drive.ex-watching #drLook,body.drive.ex-watching #drHint{display:none;}
@media (hover:none){
  body.drive.ex-watching #drSpeed{display:none;}   /* đồng hồ giữa trên đè dòng "Đang xem" */
}
/* Nút tiếng xe 🔊 / 🔇 (explore/drive/sound.ts): vùng chạm 44 px. Máy tính: giữa đáy (bản đồ nhỏ trái, đồng hồ phải). Cảm ứng: trên cần gạt (đáy trái;
   đáy giữa ở 390 px chỉ còn ≈ 32 px giữa cần gạt và PHANH). #drHud dir="ltr" nên ar không lật. Chế độ xem: không có xe của mình nên ẩn */
#drSoundBtn{display:none;}
body.drive:not(.ex-watching) #drSoundBtn{display:flex;align-items:center;justify-content:center;position:fixed;pointer-events:auto;left:50%;transform:translateX(-50%);bottom:calc(14px + env(safe-area-inset-bottom,0px));width:44px;height:44px;margin:0;padding:0;box-sizing:border-box;font-size:20px;line-height:1;color:var(--text);background:var(--panel);border:1px solid var(--panel-line);border-radius:50%;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent;}
body.drive #drSoundBtn[aria-pressed="true"]{border-color:var(--gold);}
body.drive #drSoundBtn:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
@media (hover:none){
  body.drive:not(.ex-watching) #drSoundBtn{left:calc(16px + env(safe-area-inset-left,0px));transform:none;bottom:calc(36px + var(--dr-pad-h,72px) + env(safe-area-inset-bottom,0px));}
}
body.drive #scene{cursor:grab;}
body.drive #scene:active{cursor:grabbing;}
/* Cảm ứng (hover:none): ngón trái cần gạt ngang dưới trái; ngón phải GA (to) và PHANH (nhỏ hơn, bên trái GA) dưới phải; vuốt vùng trống xoay camera.
   Kích thước từ CONFIG.drive.touch qua biến --dr-*; màn hẹp co theo bề rộng để ba nút không chồng nhau ở 390 px. Bản đồ nhỏ lên trái dưới hàng nút ⚙ / Thoát, đồng hồ giữa trên (đáy dành cho điều khiển) */
@media (hover:none){
  body.drive #drLook{display:block;position:fixed;pointer-events:auto;touch-action:none;left:0;right:0;bottom:0;top:calc(56px + env(safe-area-inset-top,0px));}
  body.drive #drSteer{display:block;position:fixed;pointer-events:auto;touch-action:none;left:calc(16px + env(safe-area-inset-left,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-pad-w,180px),38vw);height:var(--dr-pad-h,72px);box-sizing:border-box;border-radius:999px;background:rgba(10,18,22,.4);border:2px solid var(--panel-line);}
  #drKnob{position:absolute;left:50%;top:50%;width:var(--dr-knob,56px);height:var(--dr-knob,56px);margin:calc(var(--dr-knob,56px) / -2) 0 0 calc(var(--dr-knob,56px) / -2);border-radius:50%;background:rgba(230,189,106,.55);border:1px solid var(--gold);pointer-events:none;}
  body.drive #drGas,body.drive #drBrake{display:flex;align-items:center;justify-content:center;position:fixed;pointer-events:auto;touch-action:none;margin:0;padding:0;box-sizing:border-box;color:var(--text);background:rgba(10,18,22,.5);border:2px solid var(--panel-line);border-radius:18px;font:700 14px/1.1 var(--font-body);text-align:center;cursor:pointer;-webkit-tap-highlight-color:transparent;}
  body.drive #drGas{right:calc(16px + env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-gas-w,92px),24vw);height:var(--dr-gas-h,124px);}
  body.drive #drBrake{right:calc(26px + min(var(--dr-gas-w,92px),24vw) + env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-brake-w,76px),19vw);height:var(--dr-brake-h,84px);}
  body.drive #drGas.on{background:rgba(230,189,106,.6);border-color:var(--gold);}
  body.drive #drBrake.on{background:rgba(214,70,60,.6);border-color:#e86a5e;}
  body.drive #drMap{left:calc(8px + env(safe-area-inset-left,0px));top:calc(56px + env(safe-area-inset-top,0px));bottom:auto;}   /* dưới hàng nút ⚙ / Thoát (hai góc trên; ar đổi chỗ hai nút) */
  body.drive #drMapNote{left:calc(8px + env(safe-area-inset-left,0px));top:calc(60px + var(--dr-map-h,128px) + env(safe-area-inset-top,0px));bottom:auto;font-size:10px;max-width:calc(50vw - 24px);}
  body.drive #drSpeed{right:auto;bottom:auto;left:50%;transform:translateX(-50%);top:calc(8px + env(safe-area-inset-top,0px));}
}
/* Dòng hướng dẫn phím của đi dạo (#stHint): cùng chỗ và kiểu với #exHint, chỉ khi có chuột (hover:hover) và không ở chế độ xem; cảm ứng đã có cần gạt */
#stHint{display:none;}
@media (hover:hover){
  body.explore.stroll:not(.ex-watching) #stHint{display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);text-align:center;max-width:calc(100vw - 200px);box-sizing:border-box;pointer-events:none;z-index:4;}
  body.compact.stroll #stHint{top:calc(64px + env(safe-area-inset-top,0px));}
}
body.stroll #scene{cursor:grab;}
body.stroll #scene:active{cursor:grabbing;}
/* Đi dạo: điều khiển cảm ứng (explore/stroll/touch.ts). #stHud là lớp phủ trong suốt, chỉ các điều khiển nhận chạm; direction:ltr để ar (RTL) vẫn giữ cần gạt bên trái tay.
   Bố cục B: cần gạt trái dưới; phải chỉ 📷; vuốt nửa phải để xoay camera. Cần gạt, vuốt chỉ hiện khi không có chuột (hover:none); 📷 hiện cả trên máy tính */
#stHud,#stPad,#stLook,#stPhoto,#stFlash{display:none;}
body.stroll #stHud{display:block;position:fixed;inset:0;z-index:4;pointer-events:none;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;}
body.ex-watching #stHud{display:none;}
#stHud button{position:fixed;align-items:center;justify-content:center;pointer-events:auto;touch-action:none;margin:0;padding:0;color:var(--text);background:var(--panel);border:1px solid var(--panel-line);border-radius:50%;font:600 13px/1 var(--font-body);cursor:pointer;-webkit-tap-highlight-color:transparent;}
body.stroll #stPhoto{display:flex;right:calc(14px + env(safe-area-inset-right,0px));top:calc(100px + env(safe-area-inset-top,0px));width:48px;height:48px;font-size:22px;}   /* dưới nút Thoát (top 56 px) */
body.compact.stroll #stPhoto{top:calc(60px + env(safe-area-inset-top,0px));}   /* nút Thoát cao 40 px ở top 8 px */
#stFlash{position:fixed;inset:0;background:#fff;opacity:0;pointer-events:none;}   /* chớp khi chụp (Task 9 bật bằng lớp .on) */
body.stroll #stFlash{display:block;}
#stFlash.on{opacity:.85;}
/* Thông báo chụp ảnh: ô riêng ở giữa mép trên (không dùng #exMpNotice của dù lượn nhiều người); chừa chỗ cho nút Thoát bên phải, hẹp thì xuống dòng */
#stToast{display:none;}
body.stroll #stToast:not([hidden]){display:block;position:fixed;left:50%;transform:translateX(-50%);top:calc(14px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);max-width:calc(100vw - 200px);box-sizing:border-box;text-align:center;pointer-events:none;z-index:5;}
