@media (hover:none){
  body.stroll #stPad{display:block;position:fixed;pointer-events:auto;touch-action:none;left:calc(24px + env(safe-area-inset-left,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:var(--st-pad,120px);height:var(--st-pad,120px);box-sizing:border-box;border-radius:50%;background:rgba(10,18,22,.4);border:2px solid var(--panel-line);}
