  body.stroll #stLook{display:block;position:fixed;pointer-events:auto;touch-action:none;right:0;width:50%;top:calc(110px + env(safe-area-inset-top,0px));bottom:0;}   /* nửa phải, dưới nút Thoát và 📷 */
  body.stroll #exMpRoster:not([hidden]){inset-inline-end:auto;right:calc(14px + env(safe-area-inset-right,0px));}   /* ar: danh sách vẫn ở phải, không đè cần gạt bên trái */
