// Chụp nền cảnh 3D thật (không giao diện) cho prototype
import { pathToFileURL } from 'node:url';
const repo = 'D:/2026 - Tuan/danang-vite';
const { serveDir } = await import(pathToFileURL(repo + '/tests/lib.mjs').href);
const { chromium } = await import(pathToFileURL(repo + '/node_modules/playwright/index.mjs').href);
const out = repo + '/prototypes/thoi-tiet-thuc/img/';
