const shot = async (name, wait = 5000) => { await page.waitForTimeout(wait); await page.screenshot({ path: out + name + '.jpg', type: 'jpeg', quality: 82 }); console.log('ok', name); };
await shot('day');
await set('weatherSel', 'rain', 'change'); await shot('rain', 9000);
await set('weatherSel', 'now', 'change'); await set('timeSlider', '55', 'input'); await shot('dusk', 9000);
await set('timeSlider', '100', 'input'); await shot('night', 7000);
await browser.close(); srv.close();
EOF
